INSERT INTO `academy_courseassignment` (`id`, `title`, `description`, `file_instruction`, `due_date`, `max_score`, `allow_late_submission`, `created_at`, `updated_at`, `agenda_id`, `assignment_type`, `is_published`) VALUES
(1, 'Algoritma, Pseudocode, dan Flowchart', 'Buatkan Algoritma, Pseudocode, serta flowchart dari pernyataan berikut ini:\r\n\r\nMenentukan apakah seorang mendapatkan diskon berdasarkan total belanja.\r\nKetentuan:\r\n\r\nJika total belanja ? Rp[...] ? Diskon [...] %\r\nJika total belanja < Rp[1000.000] ? Tidak ada diskon\r\n\r\nNilai total belanja merupakan: akumulasi total belanja mahasiswa tersebut dalam 1 bulan..\r\nNilai Diskon merupakan: tanggal lahir dari mahasiswa tersebut..', '', '2026-02-04 15:59:00.000000', 100, 0, '2026-01-21 03:57:11.429326', '2026-02-01 06:48:27.174163', 3, 'individual', 1),
(2, 'Lembar Kerja', 'Silahkan diunggah, riwayat coding menggunakan python..', '', '2026-02-06 04:30:00.000000', 100, 0, '2026-02-06 02:59:02.320897', '2026-02-12 13:29:44.569349', 4, 'individual', 1),
(3, 'Lembar Kerja Biner, Bitwise', 'silahkan dikumpul lembar kerjanya..', '', '2026-02-13 06:00:00.000000', 100, 0, '2026-02-13 04:00:23.462166', '2026-02-13 04:02:24.475449', 6, 'individual', 1),
(4, 'Lembar Kerja', 'Silahkan dikumpul tepat waktu, tugas lembar kerja kelompok agenda 5 dengan melakukan modifikasi variabel, logika, dan level statment lebih kompleks, dokumentasi di upload di repositori github..', '', '2026-02-21 15:59:00.000000', 100, 0, '2026-02-20 03:33:33.764875', '2026-02-20 04:03:43.584972', 5, 'group', 1),
(5, 'Analisis Hubungan Kurva LM dan LS', 'Mahasiswa diminta menjelaskan hubungan antara kurva LM (Liquidity Money) dan kurva LS (Liquidity Supply) dalam pasar uang, pada halaman 13-18 pada file yang saya lampirkan.. Penjelasan dibuat dalam format video yang dan link di upload di form di bawah ini..Selamat mengerjakan..', 'course/assignments/instructions/IS_LM_Mode.pptx', '2026-03-11 15:59:00.000000', 100, 1, '2026-03-06 02:35:18.297343', '2026-03-12 08:06:02.806597', 37, 'individual', 1),
(6, 'Lembar Kerja 7 - Control Flow', 'Silahkan unggah lembar kerja pada pertemuan ke 7, dapat menggunakan github, google colabs..', '', '2026-03-15 15:59:00.000000', 100, 0, '2026-03-09 06:39:07.065900', '2026-03-09 06:39:07.065917', 51, 'individual', 1),
(7, 'Lembar Kerja', 'Silahkan drop lembar kerja untuk pertemuan terkait Control Flow', '', '2026-03-16 15:59:00.000000', 100, 0, '2026-03-12 02:56:31.952558', '2026-03-12 02:56:31.952583', 49, 'individual', 1),
(8, 'Collecting Data Variabel Ekonomi Suatu Negara', 'Kumpulkan data minimal 10 tahun terakhir pada variabel-variabel makroekonomi suatu negara.  Gunakan sumber data valid (Gunakan portal data resmi dan terpercaya pemerintah terkait), seperti situs Bank Sentral negara terkait, World Bank, IMF, atau UNDP, etc) \r\n\r\n- https://data.worldbank.org/ \r\n- https://www.imf.org/en/data\r\n- https://hdr.undp.org/data-center/country-insights#/ranks\r\n\r\nDan sumber lain yang tervalidasi, misalnya portal data resmi negara terkait..\r\n\r\nJangan menggunakan data bersumber dari generate AI..\r\nSilahkan download file csvnya, jangan merubah nama variabel dalam kolom template data yang saya sediakan..', 'course/assignments/instructions/template_data_ekonomi_negara.csv', '2026-04-02 15:59:00.000000', 100, 0, '2026-03-12 08:04:11.524874', '2026-03-15 02:36:16.363765', 40, 'group', 1),
(9, 'Lembar Kerja - Function', 'Silahkan drop catatan/lembar kerja dalam pertemuan ini', '', '2026-03-23 15:59:00.000000', 99, 0, '2026-03-16 03:55:13.607292', '2026-03-16 03:55:13.607315', 52, 'individual', 1),
(10, 'Lembar Kerja - Function', 'Silahkan drop catatan/lembar kerja dalam pertemuan ini', '', '2026-03-23 15:59:00.000000', 100, 0, '2026-03-16 03:55:41.765025', '2026-03-16 03:55:41.765037', 53, 'individual', 1),
(11, 'Design Figma', 'Silahkan drop url design figma/individu/kelompok/', '', '2026-03-17 14:00:00.000000', 100, 0, '2026-03-17 06:09:44.123125', '2026-03-17 07:03:13.504882', 54, 'individual', 1);
